WFJ.Data.add("gossip", {
  ["6903d2b22e0556db"] = { "Impressionante, maestro. La tua inettitudine è impressionante.", "." },
  ["69074cf85d087283"] = { "Gli abitanti delle ⟦Westfall=Marche Occidentali⟧ non perdoneranno l'abbandono di Roccavento.", "." },
  ["69104cf592eea807"] = { "Tu fregato me per bene, capo! Come tu passato Slip'kik?? Io furbo però, io guardo prossima volta! Har har!\n\nNessuno passa più Slip'kik. Slip'kik promette!", "." },
  ["691b0dc1f683eadc"] = { "Cosa sai dirmi dell'orso Ursangous?", "." },
  ["691fd87b4d9d820d"] = { "Se hai tempo, ⟦Grimclaw=Truceartiglio⟧ e il suo padrone Volcor avrebbero bisogno del tuo aiuto. Se ti interessa, parla ancora con me...", "." },
  ["69240c5612381780"] = { "Ah, giusto in tempo per la tua purificazione, {race}. Toglierò con la cera le impurità dalla tua anima.", "." },
  ["692452f7eaaf864a"] = { "Dubito che tu abbia avuto molte occasioni di vedere una creatura simile. Questi destrieri demoniaci renderanno i tuoi viaggi molto più rapidi facendoti da cavalcatura, finché riuscirai a controllarli. Però sono difficili da controllare, quindi non provarci finché non ti senti all'altezza.", "." },
  ["6937f9b6180109ed"] = { "EVVAI! Ce l'ho fatta!", "." },
  ["69530ba730db59e1"] = { "Whirlaxis! Ho il tuo scettro! Ti ordino di entrare in questo mondo!", "." },
  ["6955cd9f5b1def85"] = { "Il miglior conservante per la carne che conoscano gli uomini e il Flagello: il Fluido per Imbalsamazioni di Soffiogelo. C'è un solo posto dove un avventuriero potrebbe trovarlo, e verrebbe da pensare che il lich da cui il fluido prende il nome non gradirebbe affatto chi si avventura laggiù.\n\nMa... se il fluido vuoi trovare, a Scholomance devi andare...", "." },
  ["695c665e697ac105"] = { "Se decidi di seguirmi, sta' in guardia. Gli animali e le bestie di ⟦Darkshore=Rivafosca⟧ non mi faranno del male, ma potrebbero cercare di farne a te, <avventuriero/avventuriera>.", "." },
  ["69630ffdb64202a2"] = { "Dopo lo spettacolo dei fuochi d'artificio metteranno fuori i calici, così potremo fare un brindisi!", "." },
  ["696629bf605985ec"] = { "Sì, mi piacerebbe proprio insegnarti un paio di cose sulla forgiatura. Prendi un grembiule e un martello e vediamo cosa riusciamo a combinare, che ne dici?", "." },
  ["69672f6a77b63174"] = { "Era ora che mi mostrassi dei risultati! Adesso te li mostro io, i risultati!", "." },
  ["696c6d86da66e0a2"] = { "Grazie per la pazienza, {name}.", "." },
  ["6976b2e0c188aeb2"] = { "La Somma Sacerdotessa non ha potuto lasciare Darnassus. Fandral è di pessimo umore.", "." },
  ["697e240ca191d9ef"] = { "%s ti guarda con aria d'attesa.", "." },
  ["698295947b029da5"] = { "Salute. Che affari hai con la famiglia Carevin? Vuoi aiutare i Carevin nella loro battaglia contro i non morti?", "." },
  ["69862ab176f4aa78"] = { "HAI FINITO LE NAVI DA MANDARE? DOV'È IL TUO CORAGGIO?", "." },
  ["698b2185e4f11f77"] = { "La Luce ti protegga, {class}.", "." },
  ["699141c4e4f1a0b8"] = { "Quale insetto osa presentarsi al cospetto dei signori del Consiglio? Un insetto che di certo desidera essere schiacciato!", "." },
  ["69930eceefe7e363"] = { "Allora, vai da Myolor, eh? È proprio laggiù... dietro di te! Ehm, forse davanti a te! Vicino alla Great Anvil!", "." },
  ["6994ab7ce211cf9a"] = { "Oh, ciao! Mi chiamo Sarah. Cosa posso fare per te?", "." },
  ["69961a7e952607a6"] = { "Parlami delle miniere.", "." },
  ["69992b88f3bbc042"] = { "Ho tutte le provviste da cucina che ti potranno mai servire, <amico/amica>!", "." },
  ["699de0ad9f92a993"] = { "Hai preso la decisione giusta, {class}. Troverai il nostro maestro di battaglia, ⟦Glordrum Steelbeard=Glordrum Barbacciaio⟧, nel Salone delle Armi. Buona fortuna, {name}!", "." },
  ["69a2a3705aad5dd5"] = { "La ⟦Light of Elune=Luce di Elune⟧ risplenda su di te, {name}! Troverai Aethalas, la nostra maestra di battaglia, sulla ⟦Warrior's Terrace=Terrazza dei Guerrieri⟧. Ti aiuterà a raggiungere la ⟦Warsong Gulch=Forra dei Cantaguerra⟧.", "." },
  ["69a5668e2272f902"] = { "Pare che i venti ti abbiano portato da me! Ti insegno volentieri l'arte della cucina, se hai voglia di imparare.", "." },
  ["69a75e72f6b1d94a"] = { "La locanda", "." },
  ["69afbf9275ba517b"] = { "La locanda", "." },
  ["69b31eb4c38a2ba3"] = { "Sono gli spiriti a guidarti da me. Come posso esserti utile?", "." },
  ["69b82965959bb45d"] = { "Smettila di strapparle i capelli!", "." },
  ["69baad7508e8c38a"] = { "Salute, mortali! I Discs of Norgannon mi hanno attivato per assistervi!", "." },
  ["69cea6b631a1eeaf"] = { "Stavo solo pensando. Fa paura stare qui fuori di questi tempi, sai? Da un momento all'altro questa parte dell'isola potrebbe sprofondare sotto i miei piedi e io finirei a capitombolare... da qualche parte? Dimmi, sai almeno cosa succede a <un/una> {race} che cade dall'isola?", "." },
  ["69cffb7c7f6f5a16"] = { "Guardati dall'inverno, amico.", "." },
  ["69d621fbd758e572"] = { "Salve, {class}. Di solito sarei in giro per le strade a vegliare sulla gente di ⟦Stormwind=Roccavento⟧, ma molte guardie di ⟦Stormwind=Roccavento⟧ stanno combattendo in terre lontane. E così eccomi qui, con un incarico provvisorio a offrire taglie, quando preferirei essere di pattuglia...", "." },
  ["69d82b9669260cb6"] = { "Lunga è la via, e dura la strada che hai percorso. Pochi raggiungono una tale posizione tra le nostre file. Sei <un/una> grande <amico/amica> dell'impero degli Zandalari, {name}.\n\n<Leggendario/Leggendaria>, forse... Sì... Forse.", "." },
  ["69dab2ba8d81d003"] = { "Devi salvarlo!", "." },
  ["69dd347588123d8f"] = { "Chi osa intralciare gli affari della ⟦Defias Brotherhood=Fratellanza dei Defias⟧? Muori, {class}!", "." },
  ["69e336cd9ab172f8"] = { "%s mescola i ⟦Bathran's Hair=Capelli di Bathran⟧...", "." },
  ["69f6f3b316b9a41e"] = { "Ho perso il mio ⟦Drape of Unyielding Strength=Drappo della Forza Inflessibile⟧. Puoi sostituirmelo?", "." },
})
